(() => {
  'use strict';
  const by = id => document.getElementById(id);
  const projects = {
    dify: {name:'Dify', category:'APPLICATION PLATFORM', strength:'Build and publish AI applications using agent/workflow authoring, knowledge, integrations, and application APIs. Cloud and self-hosted deployment are available.', title:'Specify the execution boundary.', difference:'Use an application platform when its authoring and deployment model fits. Our architecture makes department authority, workspace ownership, recovery semantics, and backend substitution explicit when those contracts must follow the organization’s systems.', integration:'A Dify app can expose an API to a governed connector. Define which layer owns the run, identity, state, and external effects before combining them.', sources:[['Dify documentation','https://docs.dify.ai/en/home']]},
    langchain: {name:'LangChain',category:'AGENT FRAMEWORK / INTEGRATIONS',strength:'Standard model and tool interfaces, Agent construction, and middleware make application assembly reusable. Its Agents build on LangGraph and can add context, guardrails, retries, and custom tool policies.',title:'Turn integrations into scoped capabilities.',difference:'The current route already benefits from this ecosystem. Our architecture specifies the department and thread behind a call, the store behind a file, the owner of a business effect, and the contract that survives a backend change.',integration:'Use LangChain components inside the LangGraph route. A Rust route preserves the same domain/tool contracts through native or service adapters.',sources:[['LangChain overview','https://docs.langchain.com/oss/python/langchain/overview']]},
    langgraph: {name:'LangGraph',category:'STATEFUL ORCHESTRATION RUNTIME',strength:'Provides low-level orchestration for long-running, stateful Agents, including checkpoint, streaming, and human-interruption primitives. It can combine model-driven decisions with deterministic steps.',title:'Keep the product contract above the runtime.',difference:'LangGraph is one supported backend here. Department resources, storage ownership, converter services, business adapters, and UI projections remain explicit application contracts. A custom Rust backend can implement them with workload-specific execution policies.',integration:'Use its state and execution primitives through the existing backend. Keep domain contracts stable when introducing a compatible Rust transport or frontend adapter.',sources:[['LangGraph overview','https://docs.langchain.com/oss/python/langgraph/overview']]},
    codex: {name:'Codex',category:'AGENT PRODUCT / OPEN HARNESS',strength:'Combines coding Agent surfaces with an open harness. SDK and app-server integrations expose conversations, streamed activity, tools, and configured sandbox/approval behavior to host applications.',title:'Own the business context around the Agent.',difference:'An embeddable harness can supply the model/tool loop. Our enterprise architecture defines how departments, private records, workspace lifetimes, resource budgets, and result delivery fit the business service. We can choose that integration or own the execution backend.',integration:'Codex can be an embedded Agent or a specialized delegated worker. An integration would bind each session to the application’s scope and tool policy; this connector is not registered in the checked source.',sources:[['Codex as an open platform','https://developers.openai.com/blog/codex-as-a-platform']]},
    claude: {name:'Claude Code',category:'CODING AGENT / PROGRAMMABLE SDK',strength:'Reads and changes code, uses commands and tools, and supports developer integrations. The Agent SDK exposes its Agent loop, tools, context management, sessions, permissions, and hooks to Python/TypeScript applications.',title:'Connect a harness to organizational authority.',difference:'The SDK can supply an Agent inside a host application. Our architecture is organized around business services and scoped resources: documents, voice, data, APIs, storage, and delivery share contracts across backend choices.',integration:'A Claude Code/SDK worker could handle a bounded coding or document task through an explicit session/adapter boundary. It is an integration option, not a current backend connection.',sources:[['Claude Code overview','https://code.claude.com/docs/en/overview'],['Agent SDK','https://code.claude.com/docs/en/agent-sdk/overview']]},
    pi: {name:'Pi',category:'MINIMAL / EXTENSIBLE AGENT HARNESS',strength:'Offers a customizable harness with extensions, skills, prompt templates, and packages. Interactive, print/JSON, RPC, and SDK modes support both personal use and embedding; session branching and context controls are available.',title:'Make extensions serve an operating contract.',difference:'Pi’s extensibility can supply building blocks for a custom Agent. Our architecture puts department authority, independent storage lifetimes, service adapters, and backend portability into one service design, with recovery and capacity policies specified at their ownership boundaries.',integration:'Embed Pi through SDK/RPC or use it as a scoped worker behind an adapter. Extensions still need to satisfy the host service’s scope, persistence, and delivery contracts.',sources:[['Pi project and documentation','https://pi.dev/']]},
    harness: {name:'Agent harness',category:'ARCHITECTURAL ROLE / NOT ONE PRODUCT',strength:'The layer surrounding a model: context assembly, tool dispatch, working environment, session management, and control hooks. Codex, Pi, and Deep Agents provide different implementations of this role.',title:'Connect the harness to the whole service.',difference:'A harness is a component of this architecture. The operating contract also connects users, department resources, persistent stores, controlled execution, tool services, and UI delivery. That relationship remains explicit when the harness or backend changes.',integration:'Keep strategy, harness, execution backend, and host application distinguishable. A harness can contain runtime responsibilities; boundaries depend on the chosen implementation.',sources:[['Deep Agents harness','https://docs.langchain.com/oss/python/deepagents/overview'],['Codex harness integration','https://developers.openai.com/blog/codex-as-a-platform']]}
  };
  function links(target, sources) {
    target.replaceChildren(...sources.map(([label, href]) => {const a=document.createElement('a');a.textContent=label+' ↗';a.href=href;a.target='_blank';a.rel='noreferrer';return a;}));
  }
  function bindTabs(root, selector, keys, select) {
    root.querySelectorAll(selector).forEach(button => {
      button.addEventListener('click', () => select(button));
      button.addEventListener('keydown', event => {
        if(!['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(event.key))return;
        event.preventDefault();const buttons=[...root.querySelectorAll(selector)];let i=buttons.indexOf(button);
        i=event.key==='Home'?0:event.key==='End'?keys.length-1:(i+(event.key==='ArrowLeft'||event.key==='ArrowUp'?-1:1)+keys.length)%keys.length;
        select(buttons[i]);buttons[i].focus();
      });
    });
  }
  const landscape=by('positioning');
  if(landscape){
    const select=button=>{const key=button.dataset.landProject,p=projects[key];landscape.querySelectorAll('[data-land-project]').forEach(b=>{const on=b===button;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});by('land-panel').setAttribute('aria-labelledby',button.id);by('land-category').textContent=p.category;by('land-project-title').textContent=p.name;by('land-strength').textContent=p.strength;by('land-our-title').textContent=p.title;by('land-our-difference').textContent=p.difference;by('land-integration').textContent=p.integration;links(by('land-source'),p.sources);by('land-status').textContent=`${p.name} selected. Compare its integration role with our enterprise execution contract.`;};
    bindTabs(landscape,'[data-land-project]',Object.keys(projects),select);select(by('land-tab-dify'));
  }
  const patterns = {
    react: {name:'ReAct',badge:'IMPLEMENTED LOOP PRIMITIVES',used:['state','policy','action','runtime'],definition:'ReAct interleaves reasoning, task actions, and environment observations. The next action can depend on evidence returned by the previous one.',steps:[['POLICY','Select an action'],['ACTION','Call a tool'],['STATE','Observe and choose again']],state:'S = { messages, actions, observations }\nπ = choose tool, revise, or answer\nstop = enough evidence or explicit limit',precision:'A modern tool-calling loop has this interaction shape; reproducing the paper’s exact prompting and evaluation setup is a separate implementation choice.',fit:'The existing model → tools → observations → model loop supplies the core mechanism. State and file routes retain working material; the request’s department remains its resource boundary.',langgraph:'Use graph state, registered tools, and the Agent loop, with application policies around resource use.',rust:'Use a model client, typed action interpreter, observation log, and scoped tool/resource adapters; persist each accepted transition.',composition:'Retrieved evidence can enter the same loop; complex requests can add plan state or delegation.',evidence:'Observed mechanism: model/tool loop, optional todos, file state, and prompt-guided query revision. These are contract mappings, not benchmark reproductions.',sources:[['ReAct / original paper','https://arxiv.org/abs/2210.03629']]},
    plan: {name:'Plan-and-Execute',badge:'PLAN PRIMITIVES / COMPOSABLE POLICY',used:['state','policy','action','runtime'],definition:'Separate a high-level planner from the executor that accomplishes each planned step. Replanning variants revise remaining steps from new observations.',steps:[['STATE','Create a plan'],['POLICY','Choose a pending step'],['ACTION','Execute and observe'],['POLICY','Update or replan']],state:'S = { goal, plan, completed_steps, observations }\nπ = planner + step executor + replanning rule\nstop = goal met or explicit budget/limit',precision:'A todo list is useful plan state. A faithful planner/executor policy additionally defines how a step is selected, completed, and revised.',fit:'The checked harness supplies mutable todos and delegation. A planner/executor controller can compose those primitives with the existing tool loop while retaining the same resource scope.',langgraph:'Represent plan state and conditional planner/executor transitions, using existing tools and state/file backends.',rust:'Define typed plan updates and an executor continuation; apply the same observation/replanning rule through the action interpreter.',composition:'A step executor can itself use ReAct, retrieve evidence, or delegate; planning depth does not change the caller’s authority.',evidence:'Observed: optional todo/file planning. Explicit split planner/executor scheduling is a policy implementation path, not an inferred guarantee of every run.',sources:[['Plan-and-Execute / primary description','https://www.langchain.com/blog/plan-and-execute-agents']]},
    reflexion: {name:'Reflexion',badge:'FEEDBACK / MEMORY POLICY EXTENSION',used:['state','policy','action','evaluate','runtime'],definition:'Use task feedback to generate a verbal reflection, retain it in episodic memory, and influence the next trial. The original method improves behavior through feedback text rather than updating model weights.',steps:[['ACTION','Attempt a task'],['EVALUATE','Assess the result'],['STATE','Save a reflection'],['POLICY','Condition the next trial']],state:'S = { trial, observations, feedback, episodic_memory }\nπ = actor + evaluator + reflection writer\nstop = success or trial budget',precision:'An explicit think tool is a reflection primitive. Reflexion also requires task evaluation and memory that is deliberately supplied to later trials.',fit:'Messages and scoped state provide a place for feedback and memory. Add the evaluator, memory selection, and trial controller as a policy module; storage and authority stay within the same framework.',langgraph:'Use actor/evaluator transitions and scoped feedback state or a memory store with explicit retention.',rust:'Store typed trial outcomes and reflection records; condition the next model call on authorized selected memory.',composition:'Reflection can improve a plan, a reactive attempt, or a search branch; memory scope and source versions remain explicit.',evidence:'Observed: explicit reflection messages and saved state. An automatic cross-trial Reflexion controller is an extension with its own evaluator and memory policy.',sources:[['Reflexion / original paper','https://arxiv.org/abs/2303.11366']]},
    tot: {name:'Tree of Thoughts',badge:'CANDIDATE / SEARCH POLICY EXTENSION',used:['state','policy','action','evaluate','runtime'],definition:'Explore alternative intermediate thought states using generation, evaluation, and a search procedure. The original work uses search over meaningful reasoning units rather than committing to one linear continuation.',steps:[['STATE','Fork candidate states'],['EVALUATE','Score or compare'],['POLICY','Keep / prune / backtrack'],['STATE','Select a continuation']],state:'S = { candidates, parent_ids, scores, frontier }\nπ = generator + evaluator + search controller\nstop = solution or search budget',precision:'Multiple samples alone are not Tree of Thoughts. The controller needs a frontier, evaluation criteria, and explicit selection/backtracking behavior.',fit:'Candidate snapshots, evaluator calls, and controlled scheduling fit the same state/action contracts. A search policy extends the runtime without redefining document, tool, or UI ownership.',langgraph:'Represent candidates in graph state and implement expansion, evaluation, and conditional search transitions.',rust:'Use versioned candidate snapshots and an explicit frontier; bound evaluator work and make result reduction deterministic.',composition:'A candidate can contain a plan or tool-grounded evidence. Side effects remain behind a separate execution boundary.',evidence:'Implementation path: a candidate-state search controller and evaluator. The reference kernel demonstrates snapshot/reducer primitives; it does not already execute ToT.',sources:[['Tree of Thoughts / original paper','https://arxiv.org/abs/2305.10601']]},
    lats: {name:'Language Agent Tree Search (LATS)',badge:'MCTS / EVALUATOR POLICY EXTENSION',used:['state','policy','action','evaluate','runtime'],definition:'Combine language-model reasoning/actions with Monte Carlo Tree Search, value evaluation, reflection, and environment feedback to explore candidate trajectories.',steps:[['POLICY','Select a tree node'],['ACTION','Expand / roll out'],['EVALUATE','Value + feedback'],['STATE','Back up search statistics']],state:'S = { trajectory_tree, visits, values, reflections }\nπ = selection + expansion + rollout + backup\nstop = solved or iteration/cost budget',precision:'LATS needs MCTS statistics, evaluation, and a search controller. A simple tool retry or parallel subagent call does not supply those semantics.',fit:'Treat LATS as a bounded search-policy module over candidate state and tool observations. Its controller chooses exploration; the runtime still governs scope, storage, budgets, and delivery.',langgraph:'Implement the tree/controller in graph state with evaluator/model nodes and an explicitly bounded iteration policy.',rust:'Use a typed trajectory tree, visit/value updates, and bounded workers; persist controller state and separate exploratory reads from effect dispatch.',composition:'A branch can use retrieval, a plan, or specialist evaluation. Search explores candidates; only authorized selected effects may be dispatched.',evidence:'Implementation path: MCTS controller, trajectory storage, value/feedback evaluation, and budget accounting. These are explicit additions to the current loop and Rust kernel.',sources:[['LATS / ICML paper','https://proceedings.mlr.press/v235/zhou24r.html']]},
    rag: {name:'RAG / Agentic RAG',badge:'IMPLEMENTED RETRIEVAL / READ PRIMITIVES',used:['state','policy','action','runtime'],definition:'Retrieval-augmented generation conditions output on retrieved external material. In Agentic RAG, the Agent also chooses when to retrieve, reformulates queries, or gathers additional evidence.',steps:[['POLICY','Choose evidence need'],['ACTION','Search then read'],['STATE','Retain source evidence'],['POLICY','Refine or answer']],state:'S = { query, candidates, source_refs, evidence }\nπ = retrieve, read, refine, or answer\nstop = supported answer or evidence gap',precision:'RAG is a grounding mechanism and can compose with other strategies. The inspected metadata search is lexical; the original RAG paper’s dense retriever/training architecture is not claimed here.',fit:'The existing compact search → selected reader → revised search path makes evidence acquisition part of the adaptive loop. Read-only knowledge and workspace routes preserve source boundaries.',langgraph:'Use the registered search/read tools and messages/file state to carry evidence and citations.',rust:'Keep the same retrieval service contracts, source identities, and access policy through typed adapters and evidence state.',composition:'Retrieved evidence can support ReAct, each planned step, a delegated task, or a search candidate.',evidence:'Observed: indexed workspace/knowledge searches, source readers, query refinement guidance, and explicit no-hit recording.',sources:[['RAG / original paper','https://arxiv.org/abs/2005.11401']]},
    multi: {name:'Multi-Agent / delegation',badge:'IMPLEMENTED TASK / SUBAGENT PRIMITIVES',used:['state','policy','action','runtime'],definition:'Delegate work to separate Agent contexts or roles and return their results to a coordinator. Context separation, message contracts, and result merge determine the collaboration semantics.',steps:[['POLICY','Define a scoped task'],['ACTION','Delegate to a role'],['STATE','Receive a result'],['POLICY','Merge / continue']],state:'S = { task_refs, child_contexts, results, provenance }\nπ = choose role + assign + merge\nstop = required results or explicit limit',precision:'Multiple Agent contexts do not grant cross-department access. A role prompt and a resource authorization policy are different mechanisms.',fit:'The existing harness supplies a general-purpose subagent and a custom transcription role. Department-to-department coordination additionally requires authorized handoff and result-sharing contracts.',langgraph:'Use the task/subagent harness with defined context inputs and outputs; add authorization at cross-domain adapters.',rust:'Represent delegated continuations and scoped capability handles; schedule children and merge their typed results.',composition:'Each delegate can use its own plan or retrieval loop. The parent receives a result without automatically inheriting broader authority.',evidence:'Observed: framework general-purpose delegation and custom transcript processing. Automatic cross-department delegation remains an explicit service extension.',sources:[['Deep Agents delegation','https://docs.langchain.com/oss/python/deepagents/overview']]},
    human: {name:'Human-in-the-Loop',badge:'REVIEW / RESUME CONTRACT EXTENSION',used:['state','policy','action','evaluate','runtime'],definition:'Pause execution at a defined decision boundary, accept authorized human feedback, and continue from the saved state. Review can approve, reject, or modify a proposed action.',steps:[['STATE','Save a proposal'],['EVALUATE','Pause for review'],['POLICY','Validate the decision'],['ACTION','Resume selected work']],state:'S = { proposal, payload_digest, reviewer_scope, continuation }\nπ = pause + approve/reject/edit + resume\nstop = completed, rejected, or expired',precision:'A displayed plan or tool card does not establish an approval gate. The review must bind the exact action, reviewer authority, and resumable continuation.',fit:'Make review a runtime boundary around consequential actions. Strategies can continue to choose the work while the application governs who may authorize its execution.',langgraph:'Use interrupt/checkpoint/resume primitives with a durable store and application-owned reviewer authentication.',rust:'Persist a typed continuation and proposal digest; validate reviewer scope, deadlines, and current authorization before effect dispatch.',composition:'Add review to a selected write from any strategy. A search branch or delegate cannot bypass that same authority boundary.',evidence:'Implementation path: approved effect adapters and review/resume state. This is a service contract to implement; the current dataset tools are read-only.',sources:[['LangGraph interrupt contract','https://docs.langchain.com/oss/python/langgraph/interrupts']]}
  };
  const patternRoot=by('agent-patterns');if(!patternRoot)return;let selected='react';
  function renderPattern(){const p=patterns[selected],rust=by('pattern-route').value==='rust',review=by('pattern-review').checked;patternRoot.querySelectorAll('[data-pattern]').forEach(b=>{const on=b.dataset.pattern===selected;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});by('pattern-panel').setAttribute('aria-labelledby','pattern-tab-'+selected);by('pattern-badge').textContent=p.badge;by('pattern-badge').classList.toggle('is-extension',!['react','rag','multi'].includes(selected));by('pattern-name').textContent=p.name;by('pattern-definition').textContent=p.definition;patternRoot.querySelectorAll('[data-pattern-primitive]').forEach(n=>n.classList.toggle('is-used',p.used.includes(n.dataset.patternPrimitive)||review&&n.dataset.patternPrimitive==='evaluate'));by('pattern-state').textContent=p.state;by('pattern-precision').textContent=p.precision;by('pattern-fit').textContent=p.fit;by('pattern-adapter-title').textContent=rust?'RUST IMPLEMENTATION PATH':'LANGGRAPH IMPLEMENTATION';by('pattern-adapter').textContent=rust?p.rust:p.langgraph;by('pattern-evidence').textContent=p.evidence;links(by('pattern-sources'),p.sources);const steps=[...p.steps];if(review)steps.push(['COMPOSED REVIEW','Authorize selected write']);by('pattern-flow').replaceChildren();steps.forEach(([type,text],i)=>{if(i){const arrow=document.createElement('b');arrow.textContent='→';arrow.setAttribute('aria-hidden','true');by('pattern-flow').append(arrow);}const node=document.createElement('div');if(type==='COMPOSED REVIEW')node.classList.add('is-review');const label=document.createElement('span'),title=document.createElement('strong');label.textContent=type;title.textContent=text;node.append(label,title);by('pattern-flow').append(node);});by('pattern-composition').textContent='Composition: '+p.composition+(review?' Selected business writes then enter an application-authorized review/resume gate. This toggle illustrates composition; it does not grant a write capability.':'');by('pattern-status').textContent=`${p.name} · ${rust?'Rust':'LangGraph'} route${review?' · review gate composed':''}. Scope and execution contracts remain explicit.`;}
  bindTabs(patternRoot,'[data-pattern]',Object.keys(patterns),button=>{selected=button.dataset.pattern;renderPattern();});by('pattern-route').addEventListener('change',renderPattern);by('pattern-review').addEventListener('change',renderPattern);renderPattern();
})();
